def _transform_selected(X, transform, dtype, selected_features, copy=True):
    """Apply a transform function to portion(s) of the columns of a data matrix."""
    if selected_features == 'all':
        X = transform(X)
    else:
        if selected_features is None:
            selected_features = np.arange(X.shape[1])
        elif not isinstance(selected_features, (list, np.ndarray)):
